pub const OUTCOMES: usize = 14;

pub fn acc(i: usize, cart: Arc<CartData>, cache: Arc<CollisionCache>) -> Rt2 {
    match i {
        0 => acc0(cart, cache),
        1 => acc1(cart, cache),
        2 => acc2(cart, cache),
        3 => acc3(cart, cache),
        4 => acc4(cart, cache),
        5 => acc5(cart, cache),
        6 => acc6(cart, cache),
        7 => acc7(cart, cache),
        8 => acc8(cart, cache),
        9 => acc9(cart, cache),
        10 => acc10(cart, cache),
        11 => acc11(cart, cache),
        12 => acc12(cart, cache),
        13 => acc13(cart, cache),
        _ => panic!("outcome {} of 14", i),
    }
}

pub fn out_slots(i: usize) -> &'static [(u32, &'static str)] {
    match i {
        0 => OUT_SLOTS_0,
        1 => OUT_SLOTS_1,
        2 => OUT_SLOTS_2,
        3 => OUT_SLOTS_3,
        4 => OUT_SLOTS_4,
        5 => OUT_SLOTS_5,
        6 => OUT_SLOTS_6,
        7 => OUT_SLOTS_7,
        8 => OUT_SLOTS_8,
        9 => OUT_SLOTS_9,
        10 => OUT_SLOTS_10,
        11 => OUT_SLOTS_11,
        12 => OUT_SLOTS_12,
        13 => OUT_SLOTS_13,
        _ => panic!("outcome {} of 14", i),
    }
}

